import Foundation

/// The very well known domains (google.com, allianz.de, admin.ch, ...) for which the domain-age check is skipped:
/// their age tells the user nothing, and asking a third party about them would only leak the user's mail.
/// `Resources/known_domains.txt` is generated by `scripts/update-known-domains.py`.
///
/// Matching is exact on the registrable domain, so look-alikes (`g00gle.com`, `google.com.evil.net`,
/// `allianz-versicherung.de`) never match, while any subdomain of a listed domain does.
struct KnownDomains: Sendable {
    let domains: Set<String>

    /// One domain per line; blank lines and `#` comments are ignored.
    init(contents: String) {
        var set = Set<String>()
        for line in contents.split(whereSeparator: \.isNewline) {
            let entry = line.trimmingCharacters(in: .whitespaces).lowercased()
            if !entry.isEmpty && !entry.hasPrefix("#") { set.insert(entry) }
        }
        domains = set
    }

    private final class BundleToken {}

    static let shared: KnownDomains = {
        let url = Bundle(for: BundleToken.self).url(forResource: "known_domains", withExtension: "txt")
        let contents = url.flatMap { try? String(contentsOf: $0, encoding: .utf8) } ?? ""
        return KnownDomains(contents: contents)
    }()

    func contains(_ registrableDomain: String) -> Bool {
        domains.contains(registrableDomain.lowercased())
    }

    /// Whether `host` is a known domain or lives under one (`mail.google.com`, `www.sparkasse.de`).
    func includes(host: String, publicSuffixes: PublicSuffixList = .shared) -> Bool {
        var name = host.lowercased()
        if name.hasSuffix(".") { name.removeLast() }
        guard let registrable = publicSuffixes.registrableDomain(of: name) else { return false }
        return domains.contains(registrable)
    }
}
